arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: #FFFFFF;
+  --surface: #FFFFFF;
+  --surface-2: #F6F7F9;
+  --text: #0F172A;
+  --muted: #475569;
+  --border: #E2E8F0;
+  --primary: #C41E3A; /* Global Aid Alliance Red */
+  --primary-2: #A9152E;
+  --on-primary: #FFFFFF;
+  --navy: #1B3A5C;
+  --on-navy: #FFFFFF;
+  --focus: rgba(196, 30, 58, .35);
+  --shadow: 0 10px 30px rgba(15, 23, 42, .10);
+  --shadow-2: 0 18px 60px rgba(15, 23, 42, .14);
+  --radius: 16px;
+  --radius-sm: 12px;
+  --radius-xs: 10px;
+  --container: 1160px;
+  --space: 8px;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family: "Work Sans", system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  font-size: 16px;
+  line-height: 1.6;
+  color: var(--text);
+  background: var(--bg);
+  text-rendering: optimizeLegibility;
+}
+
+img{max-width:100%; height:auto; display:block}
+a{color:inherit}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:auto;
+  width:1px;
+  height:1px;
+  overflow:hidden;
+}
+.skip-link:focus{
+  left: 12px;
+  top: 12px;
+  width:auto;
+  height:auto;
+  padding: 10px 12px;
+  border-radius: 10px;
+  background: var(--navy);
+  color: var(--on-navy);
+  z-index: 2000;
+  box-shadow: var(--shadow);
+}
+
+.container{
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 0 20px;
+}
+
+.sr-only{
+  position:absolute;
+  width:1px;
+  height:1px;
+  padding:0;
+  margin:-1px;
+  overflow:hidden;
+  clip:rect(0,0,0,0);
+  white-space:nowrap;
+  border:0;
+}
+
+.section{
+  padding: 72px 0;
+}
+@media (max-width: 768px){
+  .section{padding: 56px 0;}
+}
+
+.section-header{
+  display:flex;
+  flex-direction:column;
+  gap: 12px;
+  margin-bottom: 28px;
+}
+.kicker{
+  display:inline-flex;
+  gap: 10px;
+  align-items:center;
+  color: var(--navy);
+  font-weight: 600;
+  letter-spacing: .02em;
+  text-transform: uppercase;
+  font-size: 12px;
+}
+.kicker::before{
+  content:"";
+  width: 10px;
+  height: 10px;
+  border-radius: 999px;
+  background: var(--primary);
+}
+.h2{
+  font-family: "Outfit", system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  font-weight: 700;
+  font-size: 40px;
+  letter-spacing: -0.02em;
+  line-height: 1.1;
+  margin:0;
+}
+.lede{
+  max-width: 72ch;
+  color: var(--muted);
+  margin:0;
+  font-size: 18px;
+}
+
+.badge{
+  display:inline-flex;
+  gap: 8px;
+  align-items:center;
+  border: 1px solid var(--border);
+  background: #fff;
+  border-radius: 999px;
+  padding: 8px 12px;
+  font-size: 14px;
+  color: var(--muted);
+}
+
+.btn{
+  appearance:none;
+  border: 1px solid transparent;
+  border-radius: 14px;
+  padding: 12px 16px;
+  font-weight: 650;
+  letter-spacing: .01em;
+  cursor:pointer;
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap: 10px;
+  transition: transform .12s ease, background-color .2s ease, border-color .2s ease, box-shadow .2s ease, color .2s ease;
+  min-height: 44px;
+}
+.btn:focus-visible{
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+.btn:active{transform: translateY(1px) scale(.99)}
+
+.btn-primary{
+  background: var(--primary);
+  color: var(--on-primary);
+  box-shadow: 0 10px 24px rgba(196, 30, 58, .20);
+}
+.btn-primary:hover{background: var(--primary-2)}
+
+.btn-secondary{
+  background: rgba(27, 58, 92, .08);
+  border-color: rgba(27, 58, 92, .18);
+  color: var(--navy);
+}
+.btn-secondary:hover{
+  background: rgba(27, 58, 92, .12);
+  border-color: rgba(27, 58, 92, .26);
+}
+
+.btn-ghost{
+  background: transparent;
+  border-color: var(--border);
+  color: var(--text);
+}
+.btn-ghost:hover{background: rgba(2, 6, 23, .04)}
+
+.btn-link{
+  background: transparent;
+  border-color: transparent;
+  padding: 10px 10px;
+  color: var(--navy);
+}
+.btn-link:hover{background: rgba(27, 58, 92, .08)}
+
+.icon{
+  width: 18px;
+  height: 18px;
+  display:inline-block;
+}
+
+/* Header */
+.site-header{
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+  background: rgba(255,255,255,.86);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid rgba(226, 232, 240, .9);
+}
+.header-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 16px;
+  padding: 12px 0;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap: 12px;
+  text-decoration:none;
+}
+.brand-mark{
+  width: 36px;
+  height: 36px;
+  border-radius: 12px;
+  background: linear-gradient(135deg, var(--primary), #E2475F);
+  display:grid;
+  place-items:center;
+  box-shadow: 0 10px 26px rgba(196, 30, 58, .22);
+}
+.brand-mark svg{width: 20px; height: 20px; color: #fff}
+.brand-name{
+  display:flex;
+  flex-direction:column;
+  line-height: 1.1;
+}
+.brand-name strong{
+  font-family: "Outfit", system-ui, sans-serif;
+  font-weight: 750;
+  letter-spacing: -0.01em;
+}
+.brand-name span{font-size: 13px; color: var(--muted)}
+
+.header-right{
+  display:flex;
+  align-items:center;
+  gap: 14px;
+}
+.utility{
+  display:flex;
+  gap: 12px;
+  align-items:center;
+  color: var(--muted);
+  font-size: 13px;
+}
+.utility a{color: inherit; text-decoration:none}
+.utility a:hover{color: var(--text)}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap: 4px;
+}
+.nav a{
+  text-decoration:none;
+  padding: 10px 12px;
+  border-radius: 12px;
+  color: var(--text);
+  font-weight: 600;
+}
+.nav a:hover{background: rgba(2,6,23,.04)}
+
+.header-cta{
+  display:flex;
+  gap: 10px;
+  align-items:center;
+}
+
+.menu-btn{
+  display:none;
+  padding: 10px 12px;
+}
+
+@media (max-width: 980px){
+  .utility{display:none}
+  .nav{display:none}
+  .menu-btn{display:inline-flex}
+}
+
+/* Mobile drawer */
+.drawer-backdrop{
+  position: fixed;
+  inset: 0;
+  background: rgba(2,6,23,.45);
+  opacity: 0;
+  pointer-events:none;
+  transition: opacity .2s ease;
+  z-index: 1200;
+}
+.drawer{
+  position: fixed;
+  top: 0;
+  right: 0;
+  height: 100dvh;
+  width: min(360px, 92vw);
+  background: #fff;
+  border-left: 1px solid var(--border);
+  transform: translateX(103%);
+  transition: transform .25s ease;
+  z-index: 1300;
+  display:flex;
+  flex-direction:column;
+}
+.drawer-header{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding: 14px 16px;
+  border-bottom: 1px solid var(--border);
+}
+.drawer-nav{
+  padding: 10px 10px 16px;
+  display:flex;
+  flex-direction:column;
+  gap: 6px;
+}
+.drawer-nav a{
+  text-decoration:none;
+  padding: 12px 12px;
+  border-radius: 14px;
+  font-weight: 650;
+  color: var(--text);
+}
+.drawer-nav a:hover{background: rgba(2,6,23,.04)}
+.drawer-footer{
+  margin-top:auto;
+  padding: 16px;
+  border-top: 1px solid var(--border);
+  display:flex;
+  flex-direction:column;
+  gap: 12px;
+}
+
+body.drawer-open{overflow:hidden}
+body.drawer-open .drawer-backdrop{opacity: 1; pointer-events:auto}
+body.drawer-open .drawer{transform: translateX(0)}
+
+/* Hero */
+.hero{
+  padding: 44px 0 24px;
+}
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.1fr .9fr;
+  gap: 26px;
+  align-items:stretch;
+}
+.hero-card{
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background:
+    radial-gradient(1200px 400px at 10% -10%, rgba(196, 30, 58, .18), transparent 60%),
+    radial-gradient(800px 400px at 90% 0%, rgba(27, 58, 92, .14), transparent 60%),
+    #fff;
+  box-shadow: var(--shadow);
+  padding: 28px;
+  overflow:hidden;
+  position:relative;
+}
+.hero-title{
+  font-family: "Outfit", system-ui, sans-serif;
+  font-weight: 800;
+  letter-spacing: -0.03em;
+  font-size: 56px;
+  line-height: 1.02;
+  margin: 0;
+}
+.hero-sub{
+  margin: 14px 0 0;
+  color: var(--muted);
+  font-size: 18px;
+  max-width: 60ch;
+}
+.hero-actions{
+  margin-top: 18px;
+  display:flex;
+  flex-wrap:wrap;
+  gap: 12px;
+}
+.hero-trust{
+  margin-top: 18px;
+  display:flex;
+  flex-wrap:wrap;
+  gap: 10px;
+}
+
+.hero-side{
+  display:flex;
+  flex-direction:column;
+  gap: 14px;
+}
+.image-card{
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow:hidden;
+  box-shadow: var(--shadow);
+  background:#fff;
+}
+.image-card figure{margin:0}
+.image-card img{width:100%; height: 280px; object-fit: cover}
+.image-card figcaption{
+  padding: 12px 14px;
+  font-size: 13px;
+  color: var(--muted);
+  display:flex;
+  justify-content:space-between;
+  gap: 12px;
+}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap: 8px;
+  padding: 8px 10px;
+  border-radius: 999px;
+  background: rgba(196, 30, 58, .08);
+  color: var(--primary);
+  border: 1px solid rgba(196, 30, 58, .18);
+  font-weight: 650;
+}
+.pill svg{width:16px;height:16px}
+
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr;}
+  .hero-title{font-size: 46px;}
+  .image-card img{height: 240px;}
+}
+@media (max-width: 520px){
+  .hero-card{padding: 22px;}
+  .hero-title{font-size: 38px;}
+}
+
+/* Mission */
+.mission{
+  background: linear-gradient(180deg, #fff, rgba(246, 247, 249, .55));
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.split{
+  display:grid;
+  grid-template-columns: 1.1fr .9fr;
+  gap: 28px;
+  align-items:start;
+}
+.card{
+  border: 1px solid var(--border);
+  background: var(--surface);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+}
+.card-pad{padding: 20px;}
+.mission-copy p{margin: 0 0 12px; color: var(--muted)}
+.mission-copy p strong{color: var(--text)}
+.quote{
+  padding: 18px;
+  border-radius: 14px;
+  background: rgba(27, 58, 92, .06);
+  border: 1px solid rgba(27, 58, 92, .14);
+}
+.quote .label{
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: .04em;
+  color: var(--navy);
+  font-weight: 700;
+}
+.quote p{margin: 8px 0 0; color: var(--text); font-weight: 600}
+.mini-list{
+  display:grid;
+  gap: 10px;
+  margin-top: 14px;
+}
+.mini-list .mini{
+  display:flex;
+  align-items:flex-start;
+  gap: 12px;
+  padding: 12px;
+  border-radius: 14px;
+  border: 1px solid var(--border);
+  background: #fff;
+}
+.mini svg{width: 18px; height: 18px; color: var(--primary); flex: 0 0 auto; margin-top: 2px}
+.mini strong{display:block; font-weight: 750}
+.mini span{display:block; color: var(--muted); font-size: 14px}
+@media (max-width: 980px){
+  .split{grid-template-columns: 1fr}
+}
+
+/* Impact stats */
+.stats{
+  background:
+    radial-gradient(900px 360px at 15% 10%, rgba(196, 30, 58, .12), transparent 65%),
+    radial-gradient(900px 360px at 85% 0%, rgba(27, 58, 92, .10), transparent 65%),
+    #fff;
+}
+.stats-grid{
+  display:grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 14px;
+}
+.stat{
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background: #fff;
+  padding: 18px;
+  box-shadow: var(--shadow);
+}
+.stat .value{
+  font-family: "Outfit", system-ui, sans-serif;
+  font-weight: 800;
+  font-size: 34px;
+  letter-spacing: -0.03em;
+  line-height: 1.05;
+}
+.stat .label{margin-top: 6px; color: var(--muted); font-weight: 600}
+.stat .hint{margin-top: 10px; color: var(--muted); font-size: 13px}
+.stat .value .unit{font-weight: 750; font-size: .72em; margin-left: 6px; color: var(--navy)}
+@media (max-width: 980px){
+  .stats-grid{grid-template-columns: repeat(2, 1fr)}
+}
+@media (max-width: 520px){
+  .stats-grid{grid-template-columns: 1fr}
+  .stat .value{font-size: 32px}
+}
+
+/* Programs accordion */
+.accordion{
+  display:grid;
+  gap: 10px;
+}
+.acc-item{
+  border: 1px solid var(--border);
+  border-radius: 16px;
+  background: #fff;
+  overflow:hidden;
+  box-shadow: var(--shadow);
+}
+.acc-btn{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+  padding: 16px 16px;
+  background: transparent;
+  border: 0;
+  cursor:pointer;
+  font-family: inherit;
+  text-align:left;
+  min-height: 56px;
+}
+.acc-btn:focus-visible{
+  outline: 3px solid var(--focus);
+  outline-offset: -3px;
+}
+.acc-title{
+  display:flex;
+  align-items:center;
+  gap: 12px;
+  font-weight: 800;
+  color: var(--text);
+}
+.acc-title svg{width: 18px; height: 18px; color: var(--primary)}
+.chev{
+  width: 18px;
+  height: 18px;
+  color: var(--muted);
+  transition: transform .2s ease;
+}
+.acc-panel{
+  max-height: 0;
+  overflow: hidden;
+  transition: max-height .25s ease;
+}
+.acc-panel-inner{
+  padding: 0 16px 16px;
+  color: var(--muted);
+}
+.acc-panel-inner p{margin: 0}
+.acc-item[data-open="true"] .chev{transform: rotate(180deg)}
+
+/* Get involved */
+.tiles{
+  display:grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 14px;
+}
+.tile{
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 18px;
+  background: #fff;
+  box-shadow: var(--shadow);
+  display:flex;
+  flex-direction:column;
+  gap: 10px;
+}
+.tile h3{
+  margin:0;
+  font-family: "Outfit", system-ui, sans-serif;
+  letter-spacing: -0.01em;
+}
+.tile p{margin: 0; color: var(--muted)}
+.tile .top{
+  display:flex;
+  justify-content:space-between;
+  align-items:flex-start;
+  gap: 12px;
+}
+.tile .top svg{width: 22px; height: 22px; color: var(--navy)}
+.tile .actions{margin-top:auto; display:flex; gap: 10px; flex-wrap:wrap}
+@media (max-width: 980px){
+  .tiles{grid-template-columns: 1fr;}
+}
+
+/* News carousel */
+.carousel{
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background: #fff;
+  box-shadow: var(--shadow);
+  overflow:hidden;
+}
+.carousel-top{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+  padding: 14px 14px;
+  border-bottom: 1px solid var(--border);
+}
+.carousel-top .hint{color: var(--muted); font-size: 13px}
+.carousel-controls{display:flex; gap: 10px}
+.icon-btn{
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  border: 1px solid var(--border);
+  background: #fff;
+  cursor:pointer;
+  display:grid;
+  place-items:center;
+  transition: background-color .2s ease, transform .12s ease, box-shadow .2s ease;
+}
+.icon-btn:hover{background: rgba(2,6,23,.04)}
+.icon-btn:active{transform: translateY(1px)}
+.icon-btn:focus-visible{outline: 3px solid var(--focus); outline-offset: 2px}
+.icon-btn:disabled{opacity:.45; cursor:not-allowed}
+.icon-btn svg{width: 18px; height: 18px; color: var(--text)}
+
+.track{
+  display:flex;
+  gap: 14px;
+  padding: 14px;
+  overflow: hidden;
+  scroll-behavior: smooth;
+}
+.news-card{
+  flex: 0 0 360px;
+  border: 1px solid var(--border);
+  border-radius: 16px;
+  overflow:hidden;
+  background: #fff;
+  box-shadow: 0 10px 28px rgba(15, 23, 42, .08);
+}
+.news-card img{height: 190px; width: 100%; object-fit: cover}
+.news-card .body{padding: 14px}
+.news-card h3{margin:0; font-family: "Outfit", system-ui, sans-serif; letter-spacing:-.01em}
+.news-card p{margin: 8px 0 0; color: var(--muted)}
+.news-card .meta{margin-top: 12px; display:flex; justify-content:space-between; align-items:center; gap: 10px; color: var(--muted); font-size: 13px}
+.news-card .tag{
+  display:inline-flex;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: rgba(27, 58, 92, .08);
+  border: 1px solid rgba(27, 58, 92, .14);
+  color: var(--navy);
+  font-weight: 650;
+}
+@media (max-width: 520px){
+  .news-card{flex-basis: 86vw}
+}
+
+/* Donate CTA */
+.donate{
+  background: linear-gradient(180deg, rgba(246, 247, 249, .6), rgba(255,255,255,1));
+  border-top: 1px solid var(--border);
+}
+.donate-grid{
+  display:grid;
+  grid-template-columns: 1.05fr .95fr;
+  gap: 14px;
+  align-items: stretch;
+}
+.donate-table{
+  width: 100%;
+  border-collapse: collapse;
+  overflow:hidden;
+  border-radius: 14px;
+  border: 1px solid var(--border);
+}
+.donate-table th,.donate-table td{
+  padding: 12px 12px;
+  border-bottom: 1px solid var(--border);
+  vertical-align:top;
+}
+.donate-table th{
+  text-align:left;
+  font-size: 13px;
+  text-transform: uppercase;
+  letter-spacing: .04em;
+  color: var(--navy);
+  background: rgba(27, 58, 92, .06);
+}
+.donate-table tr:last-child th,.donate-table tr:last-child td{border-bottom:0}
+.donate-note{color: var(--muted); margin: 12px 0 0}
+@media (max-width: 980px){
+  .donate-grid{grid-template-columns: 1fr}
+}
+
+/* Footer */
+.footer{
+  border-top: 1px solid var(--border);
+  background: #0B1220;
+  color: rgba(255,255,255,.88);
+}
+.footer a{color: rgba(255,255,255,.88)}
+.footer a:hover{color:#fff}
+.footer-grid{
+  display:grid;
+  grid-template-columns: 1.2fr 1fr 1fr 1fr;
+  gap: 18px;
+  padding: 40px 0;
+}
+.footer h3{
+  font-family: "Outfit", system-ui, sans-serif;
+  margin: 0 0 10px;
+}
+.footer ul{margin:0; padding:0; list-style:none; display:grid; gap: 8px}
+.footer li a{text-decoration:none}
+.footer .small{color: rgba(255,255,255,.68); font-size: 13px; margin-top: 10px}
+.footer-bottom{
+  border-top: 1px solid rgba(226, 232, 240, .18);
+  padding: 16px 0;
+  display:flex;
+  flex-wrap:wrap;
+  justify-content:space-between;
+  gap: 12px;
+  align-items:center;
+}
+.social{display:flex; gap: 10px; flex-wrap:wrap}
+.social a{
+  text-decoration:none;
+  padding: 8px 10px;
+  border-radius: 12px;
+  border: 1px solid rgba(226,232,240,.16);
+}
+.social a:hover{border-color: rgba(226,232,240,.32)}
+@media (max-width: 980px){
+  .footer-grid{grid-template-columns: 1fr 1fr}
+}
+@media (max-width: 520px){
+  .footer-grid{grid-template-columns: 1fr}
+}
+
+/* Modal */
+.modal-backdrop{
+  position: fixed;
+  inset: 0;
+  background: rgba(2, 6, 23, .56);
+  display:none;
+  align-items:center;
+  justify-content:center;
+  padding: 18px;
+  z-index: 2000;
+}
+.modal-backdrop[data-open="true"]{display:flex}
+.modal{
