+  border-top: 1px solid var(--border);
+}
+.donate-grid{
+  display:grid;
+  grid-template-columns: 1.05fr .95fr;
+  gap: 14px;
+  align-items: stretch;
+}
+.donate-table{
+  width: 100%;
+  border-collapse: collapse;
+  overflow:hidden;
+  border-radius: 14px;
+  border: 1px solid var(--border);
+}
+.donate-table th,.donate-table td{
+  padding: 12px 12px;
+  border-bottom: 1px solid var(--border);
+  vertical-align:top;
+}
+.donate-table th{
+  text-align:left;
+  font-size: 13px;
+  text-transform: uppercase;
+  letter-spacing: .04em;
+  color: var(--navy);
+  background: rgba(27, 58, 92, .06);
+}
+.donate-table tr:last-child th,.donate-table tr:last-child td{border-bottom:0}
+.donate-note{color: var(--muted); margin: 12px 0 0}
+@media (max-width: 980px){
+  .donate-grid{grid-template-columns: 1fr}
+}
+
