+.modal-backdrop{
+  position: fixed;
+  inset: 0;
+  background: rgba(2, 6, 23, .56);
+  display:none;
+  align-items:center;
+  justify-content:center;
+  padding: 18px;
+  z-index: 2000;
+}
+.modal-backdrop[data-open="true"]{display:flex}
+.modal{
+  width: min(720px, 96vw);
+  background: #fff;
+  border-radius: 18px;
+  box-shadow: var(--shadow-2);
+  overflow:hidden;
+  border: 1px solid rgba(226, 232, 240, .9);
+}
+.modal-header{
+  display:flex;
+  justify-content:space-between;
+  align-items:flex-start;
+  gap: 14px;
+  padding: 16px 16px;
+  border-bottom: 1px solid var(--border);
+}
+.modal-title{
+  margin:0;
+  font-family: "Outfit", system-ui, sans-serif;
+  letter-spacing: -.01em;
+}
+.modal-body{padding: 16px}
+.modal-grid{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 16px;
+}
+.amount-grid{
+  display:grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 10px;
+}
+.amount{
+  width:100%;
+  border: 1px solid var(--border);
+  border-radius: 14px;
+  background: #fff;
+  padding: 12px 10px;
+  cursor:pointer;
+  text-align:left;
+  min-height: 56px;
+  transition: border-color .2s ease, box-shadow .2s ease, transform .12s ease;
+}
+.amount:hover{border-color: rgba(196,30,58,.35); box-shadow: 0 10px 20px rgba(196,30,58,.10)}
