+
+.field{
+  display:grid;
+  gap: 6px;
+}
+.field label{font-weight: 650}
+.field input{
+  border: 1px solid var(--border);
+  border-radius: 14px;
+  padding: 12px 12px;
+  font: inherit;
+  min-height: 44px;
+}
+.field input:focus-visible{outline: 3px solid var(--focus); outline-offset: 2px}
+.help{color: var(--muted); font-size: 13px}
+
+.modal-actions{
+  margin-top: 14px;
+  display:flex;
+  justify-content:space-between;
+  gap: 12px;
+  align-items:center;
+  flex-wrap:wrap;
+}
+.secure{
+  display:flex;
+  align-items:center;
+  gap: 8px;
+  color: var(--muted);
+  font-size: 13px;
+}
+.secure svg{width: 16px; height: 16px; color: var(--navy)}
+
+@media (max-width: 820px){
+  .modal-grid{grid-template-columns: 1fr}
